sheet = 'W0::Transition probabilities'
rows = data_rows(sheet, {'G': 'number', 'H': 'string', 'I': 'string'}, 390, 398)
prob_map = {}
for r in rows:
    p = num(sheet, f'G{r}')
    frm = cell(sheet, f'H{r}')
    to = cell(sheet, f'I{r}')
    prob_map[(frm, to)] = p

states = ['Idle', 'Active', 'Done']
# step 0: Idle = 1.0, Active = 0.0, Done = 0.0
dist = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}

for step in range(4):
    new_dist = {s: 0.0 for s in states}
    for frm in states:
        p_frm = dist[frm]
        if p_frm == 0:
            continue
        for to in states:
            p_trans = prob_map.get((frm, to), 0.0)
            new_dist[to] += p_frm * p_trans
    dist = new_dist

result = round(dist['Done'], 6)

